changeSet.sql:
with completed_bdr_requests as (select account_id, COALESCE((payload->'bdr'->>'isApplicationForFreeAllocation')::boolean, false) as is_fa from request where type='BDR' and status='COMPLETED')
insert into baseline_data_report_free_allocation (id, account_id, free_allocation)
select nextval('baseline_data_report_free_allocation_seq'), account_id, is_fa from completed_bdr_requests;
